<script setup lang="ts">
import { ref, computed, watch, onBeforeUnmount } from 'vue'
import { api } from '@/api/aippt'
import type { Block, Theme, Slot, EditableBlockCommit } from '../render/types'
import { mergeTextCss, boxCss } from '../render/blockStyle'
import { pt, resolveColor } from '../render/style'
import EditableText from './EditableText.vue'
import ChartView from './ChartView.vue'
const props=withDefaults(defineProps<{block:Block;theme:Theme;slot:Slot;editable?:boolean}>(),{editable:false});const emit=defineEmits<{commit:[id:string,body:EditableBlockCommit]}>();const image=ref(''),imageError=ref(false);let version=0
const chrome=computed(()=>boxCss(props.theme,props.block.style)),textStyle=computed(()=>mergeTextCss(props.theme,props.slot.text_style||'body',props.block.style))
function style(name:any){return mergeTextCss(props.theme,name,props.block.style)}
function commit(body:EditableBlockCommit){emit('commit',props.block.id,body)}
watch(()=>props.block.type==='image'?props.block.url:null,async url=>{const current=++version;if(image.value)URL.revokeObjectURL(image.value);image.value='';imageError.value=false;if(!url)return;try{if(!/^\/(aippt\/)?assets\//.test(url))throw new Error('图片资源需要所属项目访问许可');const blob=await api.binary(url);if(current===version)image.value=URL.createObjectURL(blob)}catch{if(current===version)imageError.value=true}},{immediate:true});onBeforeUnmount(()=>{version++;if(image.value)URL.revokeObjectURL(image.value)})
</script>
<template><div class="block-content" :style="chrome">
<EditableText v-if="block.type==='text'" :value="block.text" :editable="editable" label="编辑文字" :style="textStyle" @commit="text=>commit({type:'text',text})"/>
<ul v-else-if="block.type==='bullets'" class="bullets" :style="style(slot.text_style||'bullet')"><li v-for="(item,i) in block.items" :key="i"><span class="marker" :style="{color:resolveColor(theme,'accent')}">{{theme.shape.bullet_marker==='index'?String(i+1).padStart(2,'0'):theme.shape.bullet_marker==='dot'?'•':'—'}}</span><EditableText :value="item" :editable="editable" :multiline="false" :label="'编辑要点 '+(i+1)" @commit="text=>commit({type:'bullets',index:i,text})" @enter="commit({type:'bullets',kind:'insert',index:i})" @empty-backspace="commit({type:'bullets',kind:'remove',index:i})"/></li></ul>
<template v-else-if="block.type==='image'"><img v-if="image" :src="image" :alt="block.alt" class="image"/><div v-else class="placeholder" role="img" :aria-label="block.alt" :style="{background:resolveColor(theme,'accent_soft'),color:resolveColor(theme,'accent')}"><svg viewBox="0 0 100 65" preserveAspectRatio="none"><circle cx="74" cy="22" r="20" fill="currentColor" opacity=".25"/><path d="M0 55L30 30L55 44L100 14V65H0Z" fill="currentColor" opacity=".2"/></svg><span>{{imageError?'图片暂不可用':'图片占位'}} · {{block.alt}}</span></div></template>
<ChartView v-else-if="block.type==='chart'" :block="block" :theme="theme"/>
<table v-else-if="block.type==='table'" class="table" :style="{borderColor:resolveColor(theme,'line')}"><thead><tr><th v-for="(cell,i) in block.header" :key="i" :style="style('table_header')"><EditableText :value="cell" :editable="editable" :label="'表头 '+(i+1)" @commit="text=>commit({type:'table',kind:'header',index:i,text})"/></th></tr></thead><tbody><tr v-for="(row,r) in block.rows" :key="r"><td v-for="(cell,c) in row" :key="c" :style="style('table_cell')"><EditableText :value="cell" :editable="editable" :label="'单元格 '+(r+1)+'-'+(c+1)" @commit="text=>commit({type:'table',kind:'cell',row:r,col:c,text})"/></td></tr></tbody></table>
<div v-else-if="block.type==='kpi'" class="kpi"><EditableText :value="block.value" :editable="editable" label="指标数值" :style="style('kpi_value')" @commit="text=>commit({type:'kpi',field:'value',text})"/><EditableText :value="block.label" :editable="editable" label="指标标签" :style="style('kpi_label')" @commit="text=>commit({type:'kpi',field:'label',text})"/><EditableText :value="block.note||''" :editable="editable" label="指标备注" :style="style('kpi_note')" @commit="text=>commit({type:'kpi',field:'note',text})"/></div>
<div v-else-if="block.type==='cards'" class="cards" :style="{gap:pt(16)}"><article v-for="(item,i) in block.items" :key="i" :style="{background:resolveColor(theme,'surface'),padding:pt(12),borderRadius:pt(theme.shape.radius_pt)}"><span v-if="item.icon" :style="style('subtitle')">{{item.icon}}</span><EditableText :value="item.title" :editable="editable" :label="'卡片标题 '+(i+1)" :style="style('subtitle')" @commit="text=>commit({type:'cards',index:i,field:'title',text})"/><EditableText :value="item.desc" :editable="editable" :label="'卡片描述 '+(i+1)" :style="style('body')" @commit="text=>commit({type:'cards',index:i,field:'desc',text})"/></article></div>
<div v-else-if="block.type==='callout'" class="callout" :style="{background:chrome.background??resolveColor(theme,block.variant==='source'?'surface':'accent_soft'),padding:pt(12),borderRadius:pt(theme.shape.radius_pt)}"><span v-if="block.icon">{{block.icon}}</span><EditableText :value="block.text" :editable="editable" label="提示文字" :style="style(block.variant==='source'?'caption':'body')" @commit="text=>commit({type:'callout',text})"/></div>
</div></template>
<style scoped>.block-content{width:100%;height:100%;box-sizing:border-box}.bullets{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:1.25cqw}.bullets li{display:flex;gap:1.3cqw}.marker{flex-shrink:0}.bullets .plain-edit{flex:1}.image{width:100%;height:100%;object-fit:cover;display:block}.placeholder{position:relative;width:100%;height:100%}.placeholder svg{width:100%;height:100%;display:block}.placeholder span{position:absolute;bottom:5%;left:5%;font-size:1.1cqw}.table{width:100%;border-collapse:collapse;table-layout:fixed}.table td,.table th{padding:.93cqw 1.25cqw;border-bottom:1px solid;text-align:left;overflow-wrap:anywhere}.kpi{padding:.8cqw 1.4cqw;display:flex;flex-direction:column;gap:.8cqw}.cards{display:flex;height:100%}.cards article{flex:1;min-width:0;display:flex;flex-direction:column;gap:.65cqw}.callout{display:flex;gap:.8cqw;height:100%;box-sizing:border-box}</style>
